def minimum_stair_climbing_cost(n,costs):
    best=[0]+[float('inf')]*n
    for step in range(1,n+1):
        best[step]=costs[step-1]+min(best[previous]+(step-previous)**2 for previous in range(max(0,step-3),step))
    return best[n]

